      if (resource === 'conversations' && action && route(url.pathname,request.method).parts[3] === 'members' && request.method === 'DELETE') { const body=await readBody(request); await env.DB.prepare('DELETE FROM conversation_members WHERE conversation_id=? AND user_id=?').bind(action,body.user_id).run(); return json({ok:true}); }
