      if (resource === 'messages' && action && route(url.pathname,request.method).parts[3] === 'receipts' && request.method === 'POST') { const body=await readBody(request); await env.DB.prepare('INSERT OR REPLACE INTO message_receipts (message_id,user_id,status) VALUES (?,?,?)').bind(action,user.id,body.status||'delivered').run(); return json({ok:true}); }
