      if (resource === 'messages' && action && route(url.pathname,request.method).parts[3] === 'read' && request.method === 'POST') { const message=await env.DB.prepare('SELECT conversation_id FROM messages WHERE id=?').bind(action).first(); if(!message)return json({error:'message_not_found'},404); const member=await env.DB.prepare('SELECT 1 FROM conversation_members WHERE conversation_id=? AND user_id=?').bind(message.conversation_id,user.id).first(); if(!member)return json({error:'not_a_member'},403); await env.DB.prepare('UPDATE messages SET read_at=? WHERE id=?').bind(now(),action).run(); return json({ok:true}); }
      if (resource === 'messages' && action && route(url.pathname,request.method).parts.length===3 && request.method === 'PATCH') { const body=await readBody(request); const changed=await env.DB.prepare('UPDATE messages SET body=?,edited_at=? WHERE id=? AND sender_id=? AND deleted_at IS NULL').bind(body.body||'',now(),action,user.id).run(); return json({ok:!!changed.meta?.changes}); }
      if (resource === 'messages' && action && route(url.pathname,request.method).parts.length===3 && request.method === 'DELETE') { const changed=await env.DB.prepare('UPDATE messages SET deleted_at=?,body=? WHERE id=? AND sender_id=?').bind(now(),'Сообщение удалено',action,user.id).run(); return json({ok:!!changed.meta?.changes}); }
      if (resource === 'messages' && route(url.pathname,request.method).parts.length===2 && request.method === 'POST') { const body=await readBody(request); const messageId=id(); const member=await env.DB.prepare('SELECT 1 FROM conversation_members WHERE conversation_id=? AND user_id=?').bind(body.conversation_id,user.id).first(); if(!member)return json({error:'not_a_member'},403); await env.DB.prepare('INSERT INTO messages (id,conversation_id,sender_id,body,media_url,reply_to_id) VALUES (?,?,?,?,?,?)').bind(messageId,body.conversation_id,user.id,body.body||'',body.media_url||null,body.reply_to_id||null).run(); const recipients=await env.DB.prepare('SELECT user_id FROM conversation_members WHERE conversation_id=? AND user_id<>?').bind(body.conversation_id,user.id).all(); for(const recipient of recipients.results||[])await env.DB.prepare('INSERT INTO notifications (id,user_id,type,payload_json) VALUES (?,?,?,?)').bind(id(),recipient.user_id,'new_message',JSON.stringify({conversation_id:body.conversation_id,message_id:messageId})).run(); return json({id:messageId},201); }
