      if (resource === 'friends' && request.method === 'GET') { const targetId=url.searchParams.get('user_id')||user.id; if(targetId!==user.id){const profile=await env.DB.prepare('SELECT privacy_json FROM profiles WHERE user_id=?').bind(targetId).first();let privacy={};try{privacy=JSON.parse(profile?.privacy_json||'{}')}catch{};const friend=await env.DB.prepare("SELECT 1 FROM friendships WHERE status='accepted' AND ((user_id=? AND friend_id=?) OR (user_id=? AND friend_id=?))").bind(user.id,targetId,targetId,user.id).first();if(privacy.friends_visibility==='private'||(privacy.friends_visibility==='friends'&&!friend))return json({error:'friends_list_hidden'},403)}const rows=await env.DB.prepare("SELECT f.*,u.display_name,u.username,u.avatar_url FROM friendships f JOIN users u ON u.id=CASE WHEN f.user_id=? THEN f.friend_id ELSE f.user_id END WHERE (f.user_id=? OR f.friend_id=?) AND f.status='accepted' ORDER BY f.updated_at DESC").bind(targetId,targetId,targetId).all(); return json({items:rows.results||[]}); }
